export class TtlCache<K, V> {
  private readonly store = new Map<K, { v: V; exp: number }>();
  constructor(private readonly ttlMs: number, private readonly max = 500) {}
  get(key: K): V | undefined {
    const e = this.store.get(key);
    return e && e.exp > performance.now() ? e.v : undefined;    // miss on expiry
  }
  set(key: K, value: V): void {
    if (this.store.size >= this.max) this.store.delete(this.store.keys().next().value!);
    this.store.set(key, { v: value, exp: performance.now() + this.ttlMs });
  }
}
